17	/* audio_capture.c — Audio capture via Vela media_recorder API.
18	 *
19	 * Wraps media_recorder in buffer mode into the simple
20	 * open / start / read / close API defined in audio_capture.h. */
21	
22	#include "voice/audio_capture.h"
23	#include "agent_config.h"
24	
25	#include <errno.h>
26	#include <media_recorder.h>
27	#include <stdio.h>
28	#include <stdlib.h>
