32	
33	static const char* TAG = "audio_cap";
34	
35	#define CAP_OPTIONS_LEN 128
36	
37	/* Audio gain multiplier to compensate for multi-channel DMIC mixing.
38	 * When board configures 6 DMIC channels but only 1 has a physical mic,
39	 * the mono mix dilutes the signal by ~6x. Set gain to compensate.
40	 * Configurable via CONFIG_AI_AGENT_AUDIO_CAPTURE_GAIN in Kconfig. */
41	#ifdef CONFIG_AI_AGENT_AUDIO_CAPTURE_GAIN
42	#define AGENT_AUDIO_CAPTURE_GAIN CONFIG_AI_AGENT_AUDIO_CAPTURE_GAIN
43	#else
44	#define AGENT_AUDIO_CAPTURE_GAIN 6
45	#endif
46	
47	struct audio_capture {
48	    void* recorder;
49	};
50	
51	static void* s_active_recorder;
52	
53	audio_capture_t* audio_capture_open(const char* dev_path,
54	    unsigned int sample_rate, unsigned int channels,
55	    unsigned int bits_per_sample)
56	{
57	    (void)dev_path; /* media framework handles routing */
58	
59	    /* Guard against stale recorder from a previous session that was
60	     * not fully closed.  media_recorder_close is asynchronous — the
61	     * underlying pcm0c stream may still be releasing when we get
62	     * here.  Force-close the stale recorder and give the audio
63	     * framework time to finish cleanup. */
64	    if (s_active_recorder) {
65	        syslog(LOG_WARNING, "[%s] force closing stale recorder\n", TAG);
66	        media_recorder_stop(s_active_recorder);
67	        media_recorder_close(s_active_recorder);
68	        s_active_recorder = NULL;
69	        usleep(100000); /* 100ms — let pcm0c stream fully release */
70	    }
71	
72	    audio_capture_t* cap = calloc(1, sizeof(*cap));
73	
74	    if (!cap) {
75	        return NULL;
76	    }
77	
78	    cap->recorder = media_recorder_open(MEDIA_SOURCE_MIC);
79	    if (!cap->recorder) {
80	        syslog(LOG_ERR, "[%s] media_recorder_open failed\n", TAG);
81	        free(cap);
82	        return NULL;
83	    }
84	
85	    /* Build options string for raw PCM capture */
86	    char opts[CAP_OPTIONS_LEN];
87	
88	    snprintf(opts, sizeof(opts),
89	        "format=s%ule:sample_rate=%u:ch_layout=%s",
90	        bits_per_sample, sample_rate,
91	        (channels == 1) ? "mono" : "stereo");
92	
93	    /* Buffer mode: url = NULL, read via media_recorder_read_data */
94	    int ret = media_recorder_prepare(cap->recorder, NULL, opts);
95	
96	    if (ret < 0) {
97	        syslog(LOG_ERR, "[%s] prepare failed: %d\n", TAG, ret);
98	        media_recorder_close(cap->recorder);
99	        free(cap);
100	        return NULL;
101	    }
102	
103	    syslog(LOG_INFO,
104	        "[%s] opened (%uHz %uch %ubit)\n",
105	        TAG, sample_rate, channels, bits_per_sample);
106	    s_active_recorder = cap->recorder;
107	    return cap;
108	}
109	
110	int audio_capture_start(audio_capture_t* cap)
111	{
112	    if (!cap || !cap->recorder) {
113	        return -EINVAL;
114	    }
115	
116	    int ret = media_recorder_start(cap->recorder);
117	
118	    if (ret < 0) {
119	        syslog(LOG_ERR, "[%s] start failed: %d\n", TAG, ret);
120	        return ret;
121	    }
122	
123	    syslog(LOG_INFO, "[%s] capture started\n", TAG);
124	    return 0;
125	}
126	
127	int audio_capture_read(audio_capture_t* cap, void* buf, size_t len)
128	{
129	    if (!cap || !cap->recorder || !buf || len == 0) {
130	        return -EINVAL;
131	    }
132	
133	    ssize_t n = media_recorder_read_data(cap->recorder, buf, len);
134	
135	    /* Apply gain to compensate for multi-channel DMIC mixing.
136	     * When 6 DMIC channels are configured but only 1 has a physical mic,
137	     * the mono downmix dilutes the signal. Amplify to restore level. */
138	#if AGENT_AUDIO_CAPTURE_GAIN > 1
139	    if (n > 0) {
140	        int16_t* samples = (int16_t*)buf;
141	        int sample_count = (int)n / 2;
142	
143	        for (int i = 0; i < sample_count; i++) {
144	            int32_t amplified = (int32_t)samples[i] * AGENT_AUDIO_CAPTURE_GAIN;
145	
146	            /* Clamp to 16-bit range to prevent overflow */
147	            if (amplified > 32767) {
148	                amplified = 32767;
149	            } else if (amplified < -32768) {
150	                amplified = -32768;
151	            }
152	
153	            samples[i] = (int16_t)amplified;
154	        }
155	    }
156	#endif
157	
158	    return (int)n;
159	}
160	
161	void audio_capture_close(audio_capture_t* cap)
162	{
163	    if (!cap) {
164	        return;
165	    }
166	
167	    if (cap->recorder) {
168	        int ret;
169	
170	        /* media_recorder_stop() internally closes the audio stream
171	         * (af_stream_stop + af_stream_close).  media_recorder_close()
172	         * then tries af_stream_close again, which logs a harmless
173	         * "ERROR: status = 1" because the stream is already closed.
174	         *
175	         * This double-close warning is benign.  Removing the stop()
176	         * call is NOT safe — media_recorder_close() alone does not
177	         * properly release the pcm0c stream, leaving it in a stale
178	         * state that blocks the next recorder open. */
179	        ret = media_recorder_stop(cap->recorder);
180	        if (ret < 0) {
181	            syslog(LOG_WARNING, "[%s] media_recorder_stop: %d\n", TAG, ret);
182	        }
183	
184	        /* Brief delay to let media framework's internal thread
185	         * finish processing the stop command before we close.
186	         * Without this, af_stream_close races with the recorder
187	         * thread's own close, causing "status = 1" errors on
188	         * BES platforms. */
189	        usleep(50 * 1000);
190	
191	        ret = media_recorder_close(cap->recorder);
192	        if (ret < 0) {
193	            syslog(LOG_WARNING, "[%s] media_recorder_close: %d\n", TAG, ret);
194	        }
195	
196	        cap->recorder = NULL;
197	        s_active_recorder = NULL;
198	    }
199	
200	    free(cap);
201	}

