1410	
1411	    if (ctx->state != MEDIA_RECORDER_STATE_IDLE || name == NULL)
1412	        return ret;
1413	
1414	    media_recorder_ctx_init(ctx);
1415	
1416	    audio_graph_open(&ctx->audio_input, name);
1417	    if (ctx->audio_input == NULL) {
1418	        MEDIA_ERR("ctx %p open audio input failed\n", ctx);
1419	        goto out;
1420	    }
1421	
1422	    pthread_attr_init(&attr);
1423	    pthread_attr_setstacksize(&attr, CONFIG_MEDIA_RECORDER_STACKSIZE);
1424	    param.sched_priority = CONFIG_MEDIA_RECORDER_PRIORITY;
1425	    pthread_attr_setschedparam(&attr, &param);
