112	int main(int argc, char* argv[])
113	{
114	    MediaPriv* priv;
115	    int ret, n, i;
116	
117	    priv = zalloc(sizeof(MediaPriv));
118	    if (!priv)
119	        return -ENOMEM;
120	
121	    for (i = 0; i < ARRAY_SIZE(g_media); i++) {
122	        ret = mediad_plugin_init(g_media[i]);
123	        if (ret < 0) {
124	            MEDIA_ERR("%s create failed ret:%d\n", g_media[i]->name, ret);
125	            goto out;
126	        }
127	    }
128	
129	    while (1) {
130	        for (n = i = 0; i < ARRAY_SIZE(g_media); i++) {
131	            if (!g_media[i]->get)
132	                continue;
133	
134	            ret = g_media[i]->get(g_media[i], &priv->fds[n], &priv->ctx[n], MAX_POLLFDS - n);
135	            if (ret < 0) {
136	                MEDIA_ERR("%s get_pollfds failed %d\n", g_media[i]->name, ret);
137	                continue;
138	            }
139	
140	            while (ret--)
141	                priv->idx[n++] = i;
142	        }
143	
144	        assert(n > 0 && n < MAX_POLLFDS);
145	
146	        poll(priv->fds, n, -1);
147	
148	        for (i = 0; i < n; i++) {
149	            if (!priv->fds[i].revents)
150	                continue;
151	
152	            ret = g_media[priv->idx[i]]->available(g_media[priv->idx[i]],
153	                &priv->fds[i], priv->ctx[i]);
154	            if (ret < 0 && ret != -EAGAIN && ret != -EPIPE)
155	                MEDIA_ERR("%s poll_available failed %d\n", g_media[priv->idx[i]]->name, ret);
156	        }
157	
158	        for (i = 0; i < ARRAY_SIZE(g_media); i++) {
159	            if (!g_media[i]->run_once)
160	                continue;
161	
162	            ret = g_media[i]->run_once(g_media[i]);
163	            if (ret < 0)
164	                MEDIA_ERR("%s run_once failed %d\n", g_media[i]->name, ret);
165	        }
166	    }
167	
168	out:
169	    MEDIA_INFO("media daemon exit\n");
170	    for (i = 0; i < ARRAY_SIZE(g_media); i++)
171	        mediad_plugin_uinit(g_media[i]);
172	
173	    free(priv);
174	    return 0;
175	}

