17	/* audio_playback.c — Streaming audio playback via media_player buffer mode.
18	 *
19	 * Uses media_player_write_data() for synchronous buffer-mode playback.
20	 * Each write_data() call blocks until the media framework consumes the
21	 * buffer, so TTS PCM chunks are played as they arrive — no temp file. */
22	
23	#include "voice/audio_playback.h"
24	#include "agent_config.h"
25	
26	#include <errno.h>
27	#include <media_player.h>
28	#include <stdio.h>
29	#include <stdlib.h>
