int snd_vela_pcm_open(snd_pcm_t **pcm, const char *name,
		snd_pcm_stream_t stream, int mode)
{
	int ret = 0, res = 0;

	const snd_pcm_config_t *top_config = NULL;
	top_config = snd_pcm_config_get_config(name);
	if (!top_config) {
		awalsa_err("pcm \"%s\": config not found\n", name);
		res = -1;
		goto out;
	}

	ret = snd_pcm_open_config(pcm, top_config, stream, mode);
	if (0 != ret) {
		awalsa_err("pcm \"%s\": snd_pcm_open_config failed (return: %d)\n", name, ret);
		res = ret;
		goto out;
	}

out:
	return res;
}

int snd_vela_pcm_close(snd_pcm_t *pcm)
{
	int ret = 0, res = 0;

	syslog(LOG_ERR, "%d, %s\n", __LINE__, __func__);
	assert(pcm);
	awalsa_debug("\n");
	if (pcm->setup && !pcm->donot_close) {
		snd_vela_pcm_drop(pcm);
		ret = snd_vela_pcm_hw_free(pcm);
		if (ret < 0)
			res = ret;
	}
	if (pcm->mmap_channels)
		snd_pcm_munmap(pcm);
	assert(pcm->ops->close);
	ret = pcm->ops->close(pcm->op_arg);
	if (ret < 0)
		res = ret;
	ret = snd_pcm_free(pcm);
	if (ret < 0)
		res = ret;

	return res;
}

int snd_vela_pcm_hw_params_malloc(snd_pcm_hw_params_t **ptr)
{
	assert(ptr);
	*ptr = calloc(1, sizeof(snd_pcm_hw_params_t));
	if (!*ptr)
		return -ENOMEM;
	return 0;
}

