/* audio_capture.c — Audio capture via board aw-alsa-lib (snd_vela_pcm).
 *
 * 2026-08-11 上板修复（P55+，mic demo -5）：原实现走 openvela
 * media_recorder 框架，但 R528 gemini-s1 固件未编译 media server
 * （CONFIG_LIB_FFMPEG / CONFIG_LIB_PFW 均未启用），
 * media_recorder_open() 恒返回 NULL → audio_capture_open 失败 → -EIO。
 * 改为直接调用板级 aw-alsa-lib（snd_vela_pcm_*），与 luncher_dm 音乐
 * 播放（dm_sound）同源、已在上板验证可用的 PCM 路径。 */

#include "voice/audio_capture.h"
#include "agent_config.h"

#include "pcm.h" /* aw-alsa-lib: snd_vela_pcm_* */

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>

static const char* TAG = "audio_cap";

/* Audio gain multiplier to compensate for multi-channel DMIC mixing.
 * When board configures 6 DMIC channels but only 1 has a physical mic,
 * the mono mix dilutes the signal by ~6x. Set gain to compensate.
 * Configurable via CONFIG_AI_AGENT_AUDIO_CAPTURE_GAIN in Kconfig. */
#ifdef CONFIG_AI_AGENT_AUDIO_CAPTURE_GAIN
#define AGENT_AUDIO_CAPTURE_GAIN CONFIG_AI_AGENT_AUDIO_CAPTURE_GAIN
#else
#define AGENT_AUDIO_CAPTURE_GAIN 6
#endif

/* 板级 PCM 卡名：与 luncher_dm dm_sound_open 一致（CONFIG_AW_AUDIO_CODEC=y） */
#define AGENT_CAPTURE_CARD "hw:audiocodec"

/* 捕获 buffer 参考 arecord：period 1024 / buffer 4096 帧 */
#define AGENT_CAPTURE_PERIOD 1024
#define AGENT_CAPTURE_BUFFER 4096

struct audio_capture {
    snd_pcm_t* pcm;
    unsigned int sample_rate;
    unsigned int channels;
    unsigned int bits_per_sample;
};

audio_capture_t* audio_capture_open(const char* dev_path,
    unsigned int sample_rate, unsigned int channels,
    unsigned int bits_per_sample)
{
    (void)dev_path; /* aw-alsa-lib 按卡名路由，无需设备路径 */

    snd_pcm_t* handle = NULL;
    snd_pcm_hw_params_t* params = NULL;
    snd_pcm_uframes_t period = AGENT_CAPTURE_PERIOD;
    snd_pcm_uframes_t buffer = AGENT_CAPTURE_BUFFER;
    int ret;

    ret = snd_vela_pcm_open(&handle, AGENT_CAPTURE_CARD,
        SND_VELA_PCM_STREAM_CAPTURE, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "[%s] snd_vela_pcm_open(%s, CAPTURE) fail %d\n",
            TAG, AGENT_CAPTURE_CARD, ret);
        return NULL;
    }

    snd_vela_pcm_hw_params_malloc(&params);
    ret = snd_vela_pcm_hw_params_any(handle, params);
    if (ret < 0) {
        syslog(LOG_ERR, "[%s] hw_params_any fail %d\n", TAG, ret);
        goto err;
    }

    snd_vela_pcm_hw_params_set_access(handle, params,
        SND_PCM_ACCESS_RW_INTERLEAVED);
    snd_vela_pcm_hw_params_set_format(handle, params, SND_PCM_FORMAT_S16_LE);
    snd_vela_pcm_hw_params_set_channels(handle, params, channels);
    snd_vela_pcm_hw_params_set_rate(handle, params, sample_rate, 0);
    snd_vela_pcm_hw_params_set_period_size(handle, params, period, 0);
    snd_vela_pcm_hw_params_set_buffer_size(handle, params, buffer);

    ret = snd_vela_pcm_hw_params(handle, params);
    snd_vela_pcm_hw_params_free(params);
    params = NULL;
    if (ret < 0) {
        syslog(LOG_ERR, "[%s] hw_params fail %d\n", TAG, ret);
        goto err;
    }

    /* SW params：捕获 start_threshold=1（有数据即自动启动），
     * 参考 arecord set_param 的 CAPTURE 分支。 */
    {
        snd_pcm_sw_params_t* sw;
        snd_pcm_sw_params_alloca(&sw);
        snd_vela_pcm_sw_params_current(handle, sw);
        snd_vela_pcm_sw_params_set_start_threshold(handle, sw, 1);
        snd_vela_pcm_sw_params_set_stop_threshold(handle, sw, buffer);
        snd_vela_pcm_sw_params_set_avail_min(handle, sw, period);
        ret = snd_vela_pcm_sw_params(handle, sw);
        if (ret < 0) {
            syslog(LOG_ERR, "[%s] sw_params fail %d\n", TAG, ret);
            goto err;
        }
    }

    audio_capture_t* cap = calloc(1, sizeof(*cap));

    if (!cap) {
        goto err;
    }

    cap->pcm = handle;
    cap->sample_rate = sample_rate;
    cap->channels = channels;
    cap->bits_per_sample = bits_per_sample;

    syslog(LOG_INFO,
        "[%s] opened %s capture (%uHz %uch %ubit)\n",
        TAG, AGENT_CAPTURE_CARD, sample_rate, channels, bits_per_sample);
    return cap;

err:
    if (params) {
        snd_vela_pcm_hw_params_free(params);
    }

    if (handle) {
        snd_vela_pcm_close(handle);
    }

    return NULL;
}

int audio_capture_start(audio_capture_t* cap)
{
    if (!cap || !cap->pcm) {
        return -EINVAL;
    }

    int ret = snd_vela_pcm_prepare(cap->pcm);

    if (ret < 0) {
        syslog(LOG_ERR, "[%s] prepare fail %d\n", TAG, ret);
        return ret;
    }

    syslog(LOG_INFO, "[%s] capture started\n", TAG);
    return 0;
}

int audio_capture_read(audio_capture_t* cap, void* buf, size_t len)
{
    if (!cap || !cap->pcm || !buf || len == 0) {
        return -EINVAL;
    }

    int frame_bytes = (int)cap->channels * ((int)cap->bits_per_sample / 8);
    snd_pcm_uframes_t frames = (snd_pcm_uframes_t)(len / (size_t)frame_bytes);
    snd_pcm_sframes_t n;
    int retries = 0;

    if (frames == 0) {
        return -EINVAL;
    }

    /* EAGAIN 短暂重试；EPIPE（xrun）prepare 恢复后重读 */
    for (;;) {
        n = snd_vela_pcm_readi(cap->pcm, buf, frames);
        if (n == -EAGAIN && retries < 10) {
            usleep(10 * 1000);
            retries++;
            continue;
        } else if (n == -EPIPE) {
            syslog(LOG_WARNING, "[%s] xrun, recovering\n", TAG);
            snd_vela_pcm_prepare(cap->pcm);
            if (retries < 10) {
                retries++;
                continue;
            }
        }

        break;
    }

    if (n < 0) {
        syslog(LOG_ERR, "[%s] readi fail %ld\n", TAG, (long)n);
        return (int)n;
    }

    size_t got = (size_t)n * (size_t)frame_bytes;

    /* Apply gain to compensate for multi-channel DMIC mixing.
     * When 6 DMIC channels are configured but only 1 has a physical mic,
     * the mono downmix dilutes the signal. Amplify to restore level. */
#if AGENT_AUDIO_CAPTURE_GAIN > 1
    if (got > 0) {
        int16_t* samples = (int16_t*)buf;
        int sample_count = (int)got / 2;

        for (int i = 0; i < sample_count; i++) {
            int32_t amplified = (int32_t)samples[i] * AGENT_AUDIO_CAPTURE_GAIN;

            /* Clamp to 16-bit range to prevent overflow */
            if (amplified > 32767) {
                amplified = 32767;
            } else if (amplified < -32768) {
                amplified = -32768;
            }

            samples[i] = (int16_t)amplified;
        }
    }
#endif

    return (int)got;
}

void audio_capture_close(audio_capture_t* cap)
{
    if (!cap) {
        return;
    }

    if (cap->pcm) {
        /* snd_vela_pcm_close 内部会 drop（若已 setup）并释放 */
        snd_vela_pcm_close(cap->pcm);
        cap->pcm = NULL;
    }

    free(cap);
}

