int snd_vela_pcm_recover(snd_pcm_t *pcm, int err, int silent)
{
	assert(pcm);
	if (err > 0)
		err = -err;
	if (err == -EPIPE) {
		const char *s = NULL;
		if (snd_vela_pcm_stream(pcm) == SND_VELA_PCM_STREAM_PLAYBACK) {
			s = "underrun";
		} else {
			s = "overrun";
		}
		if (silent == 0) {
			awalsa_err("%s occured\n", s);
		}
		err = snd_vela_pcm_prepare(pcm);
		if (err < 0) {
			awalsa_err("cannot recovery from %s, prepare return: %d",
				s, err);
			return err;
		}
		return 0;
	} else if (err == -ESTRPIPE) {
		awalsa_info("resume...\n");
		while ((err = snd_vela_pcm_resume(pcm)) == -EAGAIN) {
			#ifdef CONFIG_KERNEL_FREERTOS
			vTaskDelay(pdMS_TO_TICKS(1));
			#elif defined(CONFIG_OS_NUTTX)
			hal_msleep(1);
			#endif
		}
		if (err < 0) {
			err = snd_vela_pcm_prepare(pcm);
			awalsa_err("cannot recovery from suspend, prepare return: %d", err);
			return err;
		}
		return 0;
	}
	return err;
}

